    Shuf1 = Builder.CreateShuffleVector(Y, W, Mask);
  } else if (Y == W) {
    // shuf (bo X, Y), (bo Z, Y) --> bo (shuf X, Z), (shuf Y)
    Shuf0 = Builder.CreateShuffleVector(X, Z, Mask);
    Shuf1 = Builder.CreateShuffleVector(Y, UnaryMask);
  } else {
    return false;
  }

  // Check if this transformation would introduce undefined behavior.
  // Specifically, prevent transformations that would result in:
  // - Division by zero (srem, sdiv, urem, udiv) with zero operands
  // - Operations that are undefined with poison values

