  if (Opcode == Instruction::SRem || Opcode == Instruction::SDiv || 
      Opcode == Instruction::URem || Opcode == Instruction::UDiv) {
    // Check if either operand is definitely zero or has zero elements
    if (isa<ConstantAggregateZero>(Shuf0) || isa<ConstantAggregateZero>(Shuf1)) {
