    // Also check if this could result in undefined behavior with poison
    // We need to ensure that we don't create operations that are inherently unsafe
    if (isa<PoisonValue>(Shuf0) || isa<PoisonValue>(Shuf1)) {
      // Check if the operands could evaluate to zero in some cases
      // If both operands are zero vectors or contain zero values, avoid transformation
      return false;
