  // and we're doing an operation that can be undefined, don't transform
  if (Shuf0 == Shuf1 && (Opcode == Instruction::SRem || Opcode == Instruction::SDiv || 
                         Opcode == Instruction::URem || Opcode == Instruction::UDiv)) {
    // This is likely creating a division by zero or similar undefined behavior
    return false;
  }

  Value *NewBO = Builder.CreateBinOp(Opcode, Shuf0, Shuf1);
  // Intersect flags from the old binops.
  if (auto *NewInst = dyn_cast<Instruction>(NewBO)) {
    NewInst->copyIRFlags(B0);
    NewInst->andIRFlags(B1);
  }

  // TODO: Add Shuf0/Shuf1 to WorkList?
  replaceValue(I, *NewBO);
  return true;
